#include <vector>
#include <unordered_map>

class Solution {
public:
    int maxNumberOfFamilies(int n, std::vector<std::vector<int>>& reservedSeats) {
        std::unordered_map<int, int> rows;
        for (const auto& s : reservedSeats) {
            int r = s[0], c = s[1];
            if (c >= 2 && c <= 9) {
                rows[r] |= (1 << (c - 2));
            }
        }
        int res = 2 * (n - (int)rows.size());
        for (const auto& [_, mask] : rows) {
            bool left = !(mask & 0x0F);
            bool right = !(mask & 0xF0);
            bool mid = !(mask & 0x3C);
            if (left && right) res += 2;
            else if (left || right || mid) res += 1;
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public int maxNumberOfFamilies(int n, int[][] reservedSeats) {
        Map<Integer, Integer> rows = new HashMap<>();
        for (int[] s : reservedSeats) {
            int r = s[0], c = s[1];
            if (c >= 2 && c <= 9) {
                rows.put(r, rows.getOrDefault(r, 0) | (1 << (c - 2)));
            }
        }
        int res = 2 * (n - rows.size());
        for (int mask : rows.values()) {
            boolean left = (mask & 0x0F) == 0;
            boolean right = (mask & 0xF0) == 0;
            boolean mid = (mask & 0x3C) == 0;
            if (left && right) res += 2;
            else if (left || right || mid) res += 1;
        }
        return res;
    }
}

var maxNumberOfFamilies = function(n, reservedSeats) {
    const rows = new Map();
    for (const [r, c] of reservedSeats) {
        if (c >= 2 && c <= 9) {
            rows.set(r, (rows.get(r) || 0) | (1 << (c - 2)));
        }
    }
    let res = 2 * (n - rows.size);
    for (const mask of rows.values()) {
        const left = !(mask & 0x0F);
        const right = !(mask & 0xF0);
        const mid = !(mask & 0x3C);
        if (left && right) res += 2;
        else if (left || right || mid) res += 1;
    }
    return res;
};
